import {VERSION,STORAGE_KEY,STEPS,RAW,TRANSFER,TASKS,ASSESSMENT,freshState,restoreState,audit,intervalReturns,cumulative,answerOK,grade,invalidate,labEvidence} from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state=freshState(),page='start',storageOK=true;try{state=restoreState(localStorage.getItem(STORAGE_KEY));}catch{storageOK=false;}const val=id=>state.fields[id]??'';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'Saved on this device':'Saving unavailable · export before leaving';nav();}
function nav(){const count=STEPS.filter(([id])=>state.done[id]).length;$('#navigation').innerHTML=STEPS.map(([id,title,min],i)=>`<a href="#${id}" ${page===id?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':String(i+1).padStart(2,'0')}</span><span>${title}<small>${min} min${state.done[id]?' · complete':''}</small></span></a>`).join('');$('#progress-label').textContent=`${count} of 8 steps complete`;$('#progress-percent').textContent=Math.round(count/8*100)+'%';$('#progress').value=count;}
const field=(id,label,area=true)=>`<label class="field" for="${id}">${label}</label>${area?`<textarea id="${id}" data-save>${esc(val(id))}</textarea>`:`<input id="${id}" data-save type="number" step="any" value="${esc(val(id))}">`}`;
const check=(id,label)=>`<label class="option"><input id="${id}" type="checkbox" data-save ${val(id)===true?'checked':''}><span>${label}</span></label>`;
const msg=id=>`<div id="feedback-${id}" class="feedback" role="status"></div>`;
function feedback(id,text,error=false){const el=$('#feedback-'+id);el.textContent=text;el.className='feedback'+(error?' error':'');el.tabIndex=-1;el.focus();}
const heading=(tag,title,lead)=>`<div class="eyebrow">${tag}</div><h1>${title}</h1><p class="lead">${lead}</p>`;
function table(rows,caption){return `<div class="table-wrap"><table><caption>${caption}</caption><thead><tr><th scope="col">Observation date</th><th scope="col">Raw (GBP/share)</th><th scope="col">Split-adjusted (GBP/share)</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.date}</th><td>${r.raw??'Unknown'}</td><td>${r.adjusted??'Unknown'}</td></tr>`).join('')}</tbody></table></div>`;}
const downloads=()=>`<p class="note-links"><a href="data/lantern-raw.csv" download>Download original CSV</a><a href="data/transfer.csv" download>Download transfer CSV</a><a href="data/dictionary.txt" download>Download data dictionary</a></p>`;
function questions(qs){return qs.map(q=>`<fieldset><legend>${q.title}</legend>${q.options.map((o,i)=>`<label class="option"><input data-save type="radio" name="${q.id}" id="${q.id}-${i}" data-field="${q.id}" value="${i}" ${val(q.id)===String(i)?'checked':''}><span>${o}</span></label>`).join('')}</fieldset>`).join('');}
function start(){return heading('CHAPTER 03 · ABOUT 3 HOURS','Trust the table.','Turn a messy fictional price file into a transparent, reviewable calculation.')+`<div class="pill-row"><span class="pill">180 minutes core</span><span class="pill">No installation</span><span class="pill">Optional Python</span></div><section class="panel"><h2>Your data desk</h2><p>This standalone chapter explains every data convention it uses. Prerequisite: subtract, divide and understand percentages. A calculator and paper are sufficient; spreadsheet software is optional. No financial account, live feed or personal data is needed.</p><p>Diagnostic: £50 becomes £51. Its price return is (51 − 50) / 50 × 100 = 2%. If this is unfamiliar, use <a href="../chapter-02/#returns">Chapter 2’s return bridge</a> first. A £100 to £50 price change is −50%; later you will examine when that can be a change in share units.</p><ol><li>Read and try each concept; check answers, then explain a correction or rejected mistake.</li><li>Audit the supplied original file, predict the calculation, run both raw and adjusted comparisons and hand-check an interval.</li><li>Transfer to a different file, respond to feedback and save a data card.</li><li>Use <a href="guide.html">the complete text and paper route</a> if JavaScript or browser storage is unavailable. There is no time limit.</li></ol>${downloads()}${check('setup','I can locate the CSV, dictionary, calculator, hints, text route, Export and Privacy & reset.')}<button data-action="setup">Confirm setup</button>${msg('start')}</section><div class="callout"><strong>Completion means documented practice.</strong><p>All concept checks, four self-reviewed explanations, the audited lab and hand check, all five transfer questions with a response to feedback, and a final data card are required. Text quality is self-reviewed; this is a formative prototype, not a credential. Pacing totals 180 minutes; learner timings have not been piloted.</p></div>`;}
function lesson(){const l=LESSONS[page];return heading('CONCEPT & PRACTICE',l.title,l.objective)+l.body+(page==='quality'?table(RAW,'Original seven rows in file order · synthetic LANTERN'):``)+`<section class="panel"><h2>Try before checking</h2>${questions(TASKS[page])}<button data-action="concept">Check this practice</button>${msg('concept')}<details><summary>Hint</summary><p>Revisit the worked example and dictionary. Distinguish what is observed, assumed and unresolved.</p></details>${field(page+'Reflection',l.reflection)}${check(page+'Criteria',l.criteria)}<label class="field" for="${page}Confidence">Confidence (optional, ungraded)</label><select data-save id="${page}Confidence"><option value="">Choose if useful</option>${['Unsure','Developing','Confident'].map(v=>`<option ${val(page+'Confidence')===v?'selected':''}>${v}</option>`).join('')}</select><button data-action="concept-save">Save explanation and step</button>${msg('save')}</section>`;}
function lab(){const latest=state.runs.at(-1);return heading('DATA LAB · 35 MINUTES','Keep the original.<br>Show every decision.','Predict, inspect, calculate, compare and revise.')+`<p>All inputs are synthetic. No fills, live prices, external cash flows, dividends, fees, taxes or forecasts. The split is verified by the supplied fictional dictionary, not inferred from the price drop. Retained intervals can span gaps.</p>${downloads()}${table(RAW,'Untouched original file · seven observations')}<section class="panel"><h2>Declare your policy</h2><label class="field" for="policy">Unresolved conflicting date values</label><select data-save id="policy"><option value="">Choose</option><option value="quarantine" ${val('policy')==='quarantine'?'selected':''}>Quarantine all conflicting values pending source evidence</option><option value="last" ${val('policy')==='last'?'selected':''}>Keep whichever appears last</option></select><p>For both runs we retain one exact duplicate, exclude unknown/invalid prices, and sort unique dates. We record rather than hide the lost observations.</p><label class="field" for="column">Price basis</label><select data-save id="column"><option value="adjusted" ${val('column')!=='raw'?'selected':''}>Split-adjusted</option><option value="raw" ${val('column')==='raw'?'selected':''}>Raw</option></select>${field('prediction','Predict the first interval and raw-versus-adjusted difference (at least 15 characters).')}<button data-action="run">Run and record audit</button>${msg('run')}${latest?renderRun(latest):'<p>No runs yet. Run adjusted, then raw; every run stays in the export.</p>'}<h3>Hand check and revise</h3><p>Independently calculate (51 / 50 − 1) × 100 for 2 → 7 January, using paper or calculator. This verifies the adjusted first interval.</p>${field('hand','Hand-checked first adjusted interval (%)',false)}${field('labReflection','Compare raw and adjusted outputs; explain a correction to your prediction, one removal decision and one unresolved limitation (at least 40 characters).')}${check('labCriteria','I checked the split share count, retained both runs, labelled actual intervals and documented excluded data without filling.')}<button data-action="lab-save">Save lab evidence</button>${msg('lab')}</section>`;}
function renderRun(run){const a=audit(RAW);return `<h3>Run ${state.runs.indexOf(run)+1} · ${run.column==='raw'?'raw':'split-adjusted'} prices</h3><p>Input: ${a.input}; retained: ${a.retained}; removed: ${a.removed}. No unknown values were filled.</p><ul>${a.issues.map(i=>`<li>${i.date}: ${i.kind}; ${i.removed} removed. ${i.reason}</li>`).join('')}</ul>${table(a.clean,'Retained observations · chronological order')}<div class="table-wrap"><table><caption>Observed interval price returns · ${run.column} basis</caption><thead><tr><th scope="col">From → to</th><th scope="col">Return (%)</th></tr></thead><tbody>${run.result.map(r=>`<tr><th scope="row">${r.from} → ${r.to}</th><td>${r.pct.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p>Cumulative over 2 → 8 January: <strong>${cumulative(run.result).toFixed(2)}%</strong>. First observation has no return. Adjusted output is 2%, 2%, cumulative 4.04%; raw first interval is −49% and cumulative −47.98%. The discrepancy reflects share units.</p><p class="mini">${state.runs.length} runs retained. Every run, input, policy and result is included in Export.</p>`;}
function assessment(){const latest=state.attempts.at(-1);return heading('INDEPENDENT TRANSFER · 25 MINUTES','A different file.<br>The same discipline.','Attempt all questions before feedback. You may use a calculator and the dictionary.')+table(TRANSFER,'New synthetic asset · split on 5 February · file order')+`<p>Use the same split-only basis. Verify the order independently. The dates are fictional observations, not a trading calendar. Criterion: 5/5 correct plus a specific response to feedback. If initially correct, explain a tempting mistake you rejected. You may revise and resubmit; all attempts are retained.</p><section class="panel">${questions(ASSESSMENT)}<button data-action="assess">Submit transfer attempt</button>${msg('assessment')}${latest?`<h3>Latest recorded attempt: ${latest.score}/5</h3><ol>${ASSESSMENT.map(q=>`<li>${latest.details.find(d=>d.id===q.id)?.correct?'Correct.':'Revisit.'} ${q.why}</li>`).join('')}</ol>`:''}${field('revision','Respond to feedback: what did you change or independently check, and why? (at least 30 characters)')}<button data-action="assessment-save">Save response and assessment</button>${msg('assessment-save')}<details><summary>Additional transfer after your first attempt</summary><p>Use adjusted prices 80, 84, 84, 85.68 on four ordered observation dates, with a verified split between the second and third. Predict each interval and compound them. Explain why adding intervals is not exact. Check: 5%, 0%, 2%; cumulative 7.10%. Keep this alternate attempt in your own notes; it is optional and not automatically graded.</p></details></section>`;}
function finish(){return heading('DATA CARD · 10 MINUTES','Make the calculation<br>reviewable.','Summarise the source, transformations and limits in a reusable record.')+`<section class="panel"><p>Write a card a colleague could use to reproduce the LANTERN result. This is your explanation; the app checks presence and self-review, not prose accuracy.</p>${field('cardSource','Source card: creator, synthetic status, version, currency, observation-date convention and split-adjustment definition (30+ characters).')}${field('cardMethod','Audit and result: original/retained rows, every removal type, ordering, date intervals, adjusted returns and hand check (30+ characters).')}${field('cardLimits','Limits and revision: unresolved source conflict, gaps/calendar, dividend exclusion and a specific correction after feedback (30+ characters).')}${check('cardCriteria','I self-reviewed all three card sections against the stated criteria and completed the earlier steps.')}<button data-action="finish">Save final card</button>${msg('finish')}<p>${STEPS.filter(([id])=>state.done[id]).length}/8 steps currently complete. Completion clears when relevant evidence changes. Export records work and all attempts; it does not certify independent financial-data expertise.</p><button data-action="export" class="secondary">Export complete chapter record</button><details><summary>Example after drafting</summary><p>“LANTERN v1.0 is synthetic GBP/share teaching data authored 31 October 2026; ISO observation dates are not a verified market calendar. Split-only prices divide pre-7 January values by two. From seven input rows I retain three: quarantine two conflicting 3 January values, exclude the unknown 6 January row and remove one exact 8 January duplicate. The 2→7 and 7→8 January adjusted intervals each return 2%; compounded 4.04%. My hand check is 51/50−1 = 2%. I replaced a daily-return label with actual intervals. No missing path, dividend return or real market conclusion can be recovered.”</p></details></section><h2>Optional primary sources</h2><ul>${SOURCES.map(([label,url])=>`<li><a href="${url}">${label}</a></li>`).join('')}</ul><p class="mini">Sources checked 31 October 2026. External reading is optional. Learner pilot and complete assistive-technology testing remain pending.</p>`;}
function render(focus=true){page=STEPS.some(([id])=>id===location.hash.slice(1))?location.hash.slice(1):'start';state.lastPage=page;const body=page==='start'?start():LESSONS[page]?lesson():page==='lab'?lab():page==='assessment'?assessment():finish();const i=STEPS.findIndex(([id])=>id===page);$('#lesson').innerHTML=body+`<aside class="callout"><strong>Optional Python consolidation · 50 extra minutes</strong><p>Try CSV-style rows, chronological returns, transparent cleaning and split adjustments. <a href="../python/?chapter=3#${page==='adjustment'?'ch3-split':page==='lab'||page==='quality'?'ch3-audit':'ch3-order'}">Open Chapter 3 Python practice →</a>. Allow 10–15 minutes once for first setup. Progress is separate; this time is beyond the 180-minute core.</p></aside><div class="bottom-nav">${i?`<a href="#${STEPS[i-1][0]}">← Previous step</a>`:'<a href="../chapter-02/">← Chapter 2</a>'}${i<7?`<a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]} →</a>`:'<a href="../chapter-04/">Continue to Chapter 4 →</a>'}</div>`;nav();if(focus)$('#lesson').focus();}
function download(){const blob=new Blob([JSON.stringify({...state,version:VERSION,exported:new Date().toISOString(),original:RAW,dictionary:'Synthetic GBP/share; split-only adjustment; ISO observation dates; no expected calendar, dividends or fills.',audit:audit(RAW)},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chapter-03-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('#announcement').textContent='Chapter record exported.';}
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-save]'))return;if(el.type==='radio'&&!el.checked)return;const id=el.dataset.field||el.id;state.fields[id]=el.type==='checkbox'?el.checked:el.value;invalidate(state,id);save();});
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='export')return download();if(action==='setup'){if(val('setup')!==true)return feedback('start','Confirm the setup checkbox first.',true);state.done.start=true;save();return feedback('start','Setup saved. Continue to Know the source.');}if(action==='concept'){const qs=TASKS[page];qs.forEach(q=>state.checked[q.id]=answerOK(q,val(q.id)));state.practiceAttempts.push({step:page,time:new Date().toISOString(),answers:qs.map(q=>({id:q.id,raw:val(q.id),correct:state.checked[q.id]}))});save();return feedback('concept',qs.map(q=>(state.checked[q.id]?'Correct. ':'Revisit. ')+q.why).join(' '),!qs.every(q=>state.checked[q.id]));}if(action==='concept-save'){if(!TASKS[page].every(q=>state.checked[q.id])||String(val(page+'Reflection')).trim().length<30||val(page+'Criteria')!==true)return feedback('save','Check both answers correctly, write at least 30 characters explaining your reasoning, and self-review the criterion.',true);state.done[page]=true;save();return feedback('save','Practice and self-reviewed explanation saved.');}if(action==='run'){if(val('policy')!=='quarantine')return feedback('run','Without authoritative evidence, keeping the last conflicting value is unsupported. Select quarantine and explain that limitation.',true);if(String(val('prediction')).trim().length<15)return feedback('run','Predict first in at least 15 characters.',true);const column=val('column')||'adjusted';state.fields.column=column;state.runs.push({column,policy:'quarantine',prediction:val('prediction'),time:new Date().toISOString(),result:intervalReturns(audit(RAW).clean,column)});state.done.lab=false;state.done.finish=false;save();render(false);return feedback('run','Run recorded. Compare another price basis, then complete the hand check and reflection.');}if(action==='lab-save'){if(!labEvidence(state))return feedback('lab','Record both raw and adjusted runs, keep the current prediction recorded, enter the 2% hand check, explain a correction and limitation (40+ characters), and self-review.',true);state.done.lab=true;save();return feedback('lab','Both price bases, hand check and reflection saved.');}if(action==='assess'){const answers=Object.fromEntries(ASSESSMENT.map(q=>[q.id,String(val(q.id))]));const result=grade(answers);state.attempts.push({answers,...result,time:new Date().toISOString()});state.done.assessment=false;state.done.finish=false;save();render(false);return feedback('assessment',`${result.score}/5. Read the feedback, revise where needed and record your response.`,!result.passed);}if(action==='assessment-save'){const a=state.attempts.at(-1);if(!a?.passed||!ASSESSMENT.every(q=>a.answers[q.id]===val(q.id))||String(val('revision')).trim().length<30)return feedback('assessment-save','Submit the current answers with 5/5 and write a specific feedback response of at least 30 characters.',true);a.revision=val('revision');state.done.assessment=true;save();return feedback('assessment-save','Transfer and response to feedback saved.');}if(action==='finish'){if(!STEPS.slice(0,-1).every(([id])=>state.done[id])||!['cardSource','cardMethod','cardLimits'].every(k=>String(val(k)).trim().length>=30)||val('cardCriteria')!==true)return feedback('finish','Complete the seven earlier steps, write all three card sections (30+ characters each), and self-review the criteria.',true);state.done.finish=true;save();return feedback('finish','Chapter complete. Export your data card and attempt record.');}});
$('#chapter-select').addEventListener('change',e=>{location.href=e.target.value==='1'?'../':`../chapter-0${e.target.value}/`;});$('#privacy-button').onclick=()=>$('#privacy-dialog').showModal();$('#close-privacy').onclick=()=>$('#privacy-dialog').close();$('#reset-progress').onclick=()=>{if(!confirm('Clear only Chapter 3 progress from this browser?'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();location.hash='start';render();save();};document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('#lesson').focus();});window.addEventListener('hashchange',()=>render());render(false);if(!storageOK)$('#save-state').textContent='Saving unavailable · export before leaving';
